	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.26.0"
)

// Config holds OpenTelemetry configuration.
type Config struct {
	ServiceName    string
	ServiceVersion string
}

// Setup initializes the OpenTelemetry SDK and returns a shutdown function.
//
// Tracing and metrics are enabled when OTEL_EXPORTER_OTLP_ENDPOINT is set;
// the standard OTEL_EXPORTER_OTLP_* env vars configure both exporters,
// honoured directly by otlptracehttp.New and otlpmetrichttp.New. In
// production the endpoint points at the cluster's OTel collector gateway
// (see fleet/docs/developer-guide/logs-and-observability.md); the gateway
// enriches signals with k8s.*, cloud.*, and deployment.environment
// attributes and forwards to Honeycomb (all clusters) and Datadog (where
// the dual-export overlay is enabled — see
// fleet/clusters/.../infrastructure.yaml).
func Setup(ctx context.Context, cfg Config) (shutdown func(context.Context) error, err error) {
	if os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT") == "" {
		slog.WarnContext(ctx, "OTEL_EXPORTER_OTLP_ENDPOINT not set, tracing and metrics disabled")
		return func(context.Context) error { return nil }, nil
	}

	res, err := resource.New(ctx,
		resource.WithAttributes(
			semconv.ServiceName(cfg.ServiceName),
			semconv.ServiceVersion(cfg.ServiceVersion),
		),
		resource.WithHost(),
		resource.WithProcessRuntimeDescription(),
	)
	if err != nil {
		return nil, fmt.Errorf("create resource: %w", err)
	}

	traceExporter, err := otlptracehttp.New(ctx)
	if err != nil {
		return nil, fmt.Errorf("create OTLP trace exporter: %w", err)
	}

	tp := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(traceExporter),
		sdktrace.WithResource(res),
		sdktrace.WithSpanProcessor(baggageSpanProcessor{}),
	)
	otel.SetTracerProvider(tp)
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
		propagation.TraceContext{},
		propagation.Baggage{},
	))

	metricExporter, err := otlpmetrichttp.New(ctx)
	if err != nil {
		_ = tp.Shutdown(ctx)
		return nil, fmt.Errorf("create OTLP metric exporter: %w", err)
	}

