// Package slogutil installs mirror-pipeline's structured logging. Each binary
// calls Install once from main, the same way it calls otelsetup.Setup.
//
// Emitting JSON is what makes log severity survive the trip to Datadog, and
// that is not cosmetic. The fleet's OTel collector agent tails container
// stdout/stderr and derives OTLP SeverityNumber from the log line itself
// (fleet/infrastructure/controllers/otel-collector/helmrelease-agent.yaml):
// a json_parser lifts a top-level `level` field into severity, with a
// regex_parser fallback for logfmt-style `level=ERROR` output. A line that
// matches neither keeps severity UNSPECIFIED, and Datadog then indexes it as
// `status:info` no matter what it says.
//
// Without an installed handler, slog falls back to its built-in default, which
// writes through the standard log package as `2026/08/10 16:10:46 ERROR msg
// key=value`. That form has no JSON object and no `level=` token, so both
// operators skip it. Every mirror-pipeline binary logged that way until
// COR-1226: 464 ERROR and 221,700 WARN lines in a single day were all indexed
// as info, which is why `status:error` log monitors on these services could
// not fire (INC-49).
//
// Deliberately no `service` attribute: for container logs the service tag comes
// from the collector's Kubernetes enrichment, not from the log body, and the
// two do not always agree — cmd/rekicker reports itself to OTel as
// "mirror-rekicker" while its pods, and therefore its Datadog service tag, are
// "rekicker". Emitting our own would risk re-tagging a service out from under
// the dashboards and monitors that already reference it.
package slogutil

import (
	"log/slog"
	"os"
	"strings"
)

// Install sets a structured handler as slog's default logger. Output goes to
// stdout as JSON, matching entiredb/slogutil and entire-api's internal/slogutil
// so all three repos land in Datadog the same way.
//
// When stdout is a terminal — a developer running a binary locally — lines are
// rendered as logfmt text instead, which stays readable by eye. That form is
// still severity-parseable by the collector's regex fallback, so the two paths
// cannot disagree about a line's severity.
//
// Safe to call more than once; the last call wins.
func Install(level slog.Level) {
	opts := &slog.HandlerOptions{Level: level}
	if isTerminal(os.Stdout) {
		slog.SetDefault(slog.New(slog.NewTextHandler(os.Stdout, opts)))
		return
	}
	slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout, opts)))
}

// LevelFromEnv reads LOG_LEVEL (debug|info|warn|error, case-insensitive),
// defaulting to Info. Lets a deployment dial verbosity without a rebuild.
// Note that the collector drops DEBUG and TRACE records before export, so
// LOG_LEVEL=debug shows up in `kubectl logs` but not in Datadog.
func LevelFromEnv() slog.Level {
	switch strings.ToLower(os.Getenv("LOG_LEVEL")) {
	case "debug":
		return slog.LevelDebug
	case "warn", "warning":
		return slog.LevelWarn
	case "error":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}

// isTerminal reports whether f is attached to a character device, which is the
// dependency-free way to tell an interactive terminal from a pipe or a
// container's captured stdout.
func isTerminal(f *os.File) bool {
	info, err := f.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

