package slogutil

import (
	"bytes"
	"encoding/json"
	"log/slog"
	"regexp"
	"strings"
	"testing"
)

// The two conditions the fleet's OTel collector agent applies to a container
// log line to decide its severity, copied from
// fleet/infrastructure/controllers/otel-collector/helmrelease-agent.yaml.
// A line matching neither keeps severity UNSPECIFIED and Datadog indexes it as
// status:info — the COR-1226 / INC-49 failure. These tests assert our output
// satisfies one of them for every level we emit.
var (
	collectorJSONBody  = regexp.MustCompile(`^\s*\{.*\}\s*$`)
	collectorLogfmtLvl = regexp.MustCompile(`level=(DEBUG|INFO|WARN|ERROR|FATAL)`)
)

func TestNonTerminalOutputCarriesSeverityForCollector(t *testing.T) {
	levels := []struct {
		log  func(*slog.Logger, string)
		want string
	}{
		{func(l *slog.Logger, m string) { l.Info(m) }, "INFO"},
		{func(l *slog.Logger, m string) { l.Warn(m) }, "WARN"},
		{func(l *slog.Logger, m string) { l.Error(m) }, "ERROR"},
	}

	for _, tc := range levels {
		t.Run(tc.want, func(t *testing.T) {
			var buf bytes.Buffer
			logger := slog.New(newHandler(&buf, slog.LevelInfo, false))
			tc.log(logger, "sync failed")

			line := strings.TrimRight(buf.String(), "\n")
			if !collectorJSONBody.MatchString(line) {
				t.Fatalf("line does not match the collector's json_parser condition, so severity would stay UNSPECIFIED: %q", line)
			}

			var rec map[string]any
			if err := json.Unmarshal([]byte(line), &rec); err != nil {
				t.Fatalf("unmarshal log line: %v (line %q)", err, line)
			}
			// The collector reads severity from attributes.level, so the key
			// must be exactly "level" and the value one of its preset names.
			if got := rec["level"]; got != tc.want {
				t.Errorf(`level = %v, want %q — collector parses severity from attributes.level`, got, tc.want)
			}
			if got := rec["msg"]; got != "sync failed" {
				t.Errorf("msg = %v, want the log message", got)
			}
		})
	}
}

func TestTerminalOutputStillCarriesSeverity(t *testing.T) {
	// The terminal branch is for local dev, but it must not be a severity
	// blind spot: logfmt text hits the collector's regex_parser fallback.
	var buf bytes.Buffer
	logger := slog.New(newHandler(&buf, slog.LevelInfo, true))
	logger.Error("sync failed")

	line := buf.String()
	if !collectorLogfmtLvl.MatchString(line) {
		t.Fatalf("terminal output does not match the collector's regex_parser fallback: %q", line)
	}
}

// The pre-fix output: slog's built-in default handler writes through the
// standard log package. Neither collector operator matches it. This test
// documents the shape that caused the bug, so a future change back to it
// fails here rather than silently in production.
func TestDefaultHandlerShapeWouldNotBeParsed(t *testing.T) {
	const line = `2026/08/10 16:10:46 ERROR Permanent sync error, terminating error="http 404"`

	if collectorJSONBody.MatchString(line) || collectorLogfmtLvl.MatchString(line) {
		t.Fatal("expected slog's default handler output to be unparseable by the collector; " +
			"if this now matches, the collector config changed and the package doc is stale")
	}
}

func TestNewHandlerRespectsLevel(t *testing.T) {
	var buf bytes.Buffer
	logger := slog.New(newHandler(&buf, slog.LevelWarn, false))
	logger.Info("should be dropped")
	if buf.Len() != 0 {
		t.Errorf("Info emitted at LevelWarn: %q", buf.String())
	}
	logger.Warn("should be kept")
	if !strings.Contains(buf.String(), "should be kept") {
		t.Errorf("Warn dropped at LevelWarn: %q", buf.String())
	}
}

func TestLevelFromEnv(t *testing.T) {
	cases := map[string]slog.Level{
		"debug":   slog.LevelDebug,
		"DEBUG":   slog.LevelDebug,
		"info":    slog.LevelInfo,
		"warn":    slog.LevelWarn,
		"warning": slog.LevelWarn,
		"error":   slog.LevelError,
		"":        slog.LevelInfo,
		"nonsense": slog.LevelInfo,
	}

	for raw, want := range cases {
		t.Run("LOG_LEVEL="+raw, func(t *testing.T) {
			t.Setenv("LOG_LEVEL", raw)
			if got := LevelFromEnv(); got != want {
				t.Errorf("LevelFromEnv() = %v, want %v", got, want)
			}
		})
	}
}

