// Attribute keys Datadog treats as reserved on an ingested log record. An app
// that emits one of these as its own slog attribute has it lifted out of the
// JSON body by the collector's json_parser and written into Datadog's reserved
// field of the same name, displacing whatever the pipeline derived.
//
// `status` is the one that bites: Datadog's status remapper reads it as the
// log's severity, and a value it cannot parse as a severity (an HTTP code, a
// job state) silently degrades the record to `status:info` — discarding the
// OTLP SeverityNumber the collector set from `level`. Verified org-wide over
// 7 days: every log carrying an app `status` of 400/401/403/404/409/500/502/503
// indexed as info, ~28k of them, across services that emit real status:error on
// their other lines. That is COR-1226's bug surviving in a second form, and it
// is invisible — the line still appears, just at the wrong severity.
//
// `source` is deliberately NOT listed. It is reserved in Datadog's own docs,
// but on this OTLP path it lands as a plain `custom.source` attribute and the
// `source:otlp_log_ingestion` tag survives intact (verified live on
// cmd/worker/syncer.go's git-sync log). Several packages use it meaningfully,
// so listing it would force churn with no defect behind it.
var reservedAttrKeys = map[string]string{
	"status":    "collides with Datadog's severity field; use http.status_code / <domain>.status",
	"service":   "collides with the service tag derived by the collector's transform/service-name",
	"host":      "collides with the host tag",
	"message":   "collides with the log message body",
	"msg":       "collides with the log message body",
	"timestamp": "collides with the log timestamp",
	"date":      "collides with the log timestamp",
	"level":     "collides with the field the collector parses severity from",
	"trace_id":  "collides with trace correlation",
	"span_id":   "collides with trace correlation",
}

// slog attribute constructors whose first argument is the attribute key.
var slogAttrCtors = map[string]bool{
	"String": true, "Int": true, "Int64": true, "Uint64": true,
	"Float64": true, "Bool": true, "Duration": true, "Time": true,
	"Any": true, "Group": true,
}

// TestNoReservedSlogAttrKeys walks every Go file in the module and fails on a
// slog attribute whose key would be swallowed by a Datadog reserved field.
// A doc comment would not have caught this: the failure mode produces no error,
// no dropped log, and no test failure anywhere else — the line simply arrives
// at the wrong severity, which is exactly how the original bug survived.
func TestNoReservedSlogAttrKeys(t *testing.T) {
	root := filepath.Join("..", "..")
	fset := token.NewFileSet()

	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			case "vendor", "gen", ".git", "node_modules":
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}

		file, parseErr := parser.ParseFile(fset, path, nil, 0)
		if parseErr != nil {
			return nil // not this test's job to police unparseable files
		}

		ast.Inspect(file, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok || len(call.Args) == 0 {
				return true
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok || !slogAttrCtors[sel.Sel.Name] {
				return true
			}
			if pkg, ok := sel.X.(*ast.Ident); !ok || pkg.Name != "slog" {
				return true
			}
			lit, ok := call.Args[0].(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			key, unquoteErr := strconv.Unquote(lit.Value)
			if unquoteErr != nil {
				return true
			}
			if why, bad := reservedAttrKeys[key]; bad {
				t.Errorf("%s: slog.%s(%q, ...) — %s",
					fset.Position(lit.Pos()), sel.Sel.Name, key, why)
			}
			return true
		})
		return nil
	})
	if err != nil {
		t.Fatalf("walk module: %v", err)
	}
}

